package api

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/hkjang/jupiq/internal/auth"
	"github.com/hkjang/jupiq/internal/secure"
	"github.com/hkjang/jupiq/internal/store"
)

// PATCH /api/v1/auth/me가 보낼 수 없는 주소를 프로덕션 배선에서 거부하는지,
// 빈 주소는 계속 허용하는지 확인한다. 거부가 없으면 메일 수신자 해석이 버리는
// 값이 users.email에 남아 그 사용자만 조용히 알림을 못 받는다.
func TestProfileEmailValidationHTTPIntegration(t *testing.T) {
	dsn := os.Getenv("JUPIQ_INTEGRATION_TEST_DSN")
	if dsn == "" {
		t.Skip("set JUPIQ_INTEGRATION_TEST_DSN to run PostgreSQL integration coverage")
	}
	ctx := context.Background()
	cipher, err := secure.NewCipher(make([]byte, 32))
	if err != nil {
		t.Fatal(err)
	}
	database, err := store.Open(ctx, dsn, cipher)
	if err != nil {
		t.Fatal(err)
	}
	defer database.Close()
	marker := fmt.Sprintf("api-profile-%d", time.Now().UnixNano())
	var userID int64
	if err := database.Pool.QueryRow(ctx, `INSERT INTO users(username,display_name,email,auth_source) VALUES($1,$1,$2,'local') RETURNING id`, marker+"-user", marker+"-keep@corp.internal").Scan(&userID); err != nil {
		t.Fatal(err)
	}
	defer func() {
		_, _ = database.Pool.Exec(ctx, `DELETE FROM users WHERE id=$1`, userID)
	}()
	user, err := database.GetUser(ctx, userID)
	if err != nil {
		t.Fatal(err)
	}
	authService := auth.NewService(database, cipher)
	_, token, expires, err := authService.CreateSession(ctx, user, "127.0.0.1", "profile-email-test")
	if err != nil {
		t.Fatal(err)
	}
	handler := New(database, authService, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	patch := func(body string) *httptest.ResponseRecorder {
		req := httptest.NewRequest(http.MethodPatch, "/api/v1/auth/me", strings.NewReader(body))
		req.AddCookie(auth.SecureCookie(token, expires, false))
		response := httptest.NewRecorder()
		handler.ServeHTTP(response, req)
		return response
	}
	storedEmail := func() string {
		t.Helper()
		var email string
		if err := database.Pool.QueryRow(ctx, `SELECT email FROM users WHERE id=$1`, userID).Scan(&email); err != nil {
			t.Fatal(err)
		}
		return email
	}

	response := patch(`{"email":"  a@corp.internal  ","display_name":" 홍길동 "}`)
	if response.Code != http.StatusOK {
		t.Fatalf("a padded but valid address must be accepted: status=%d body=%s", response.Code, response.Body.String())
	}
	if body := response.Body.String(); !strings.Contains(body, `"email":"a@corp.internal"`) || !strings.Contains(body, `"display_name":"홍길동"`) {
		t.Fatalf("the response must carry trimmed values: %s", body)
	}
	if got := storedEmail(); got != "a@corp.internal" {
		t.Fatalf("users.email must be stored trimmed: %q", got)
	}

	// 비어 있지 않고 보낼 수 없는 주소만 400이다.
	response = patch(`{"email":"nonsense","display_name":"홍길동"}`)
	if response.Code != http.StatusBadRequest || !strings.Contains(response.Body.String(), `"code":"invalid_email"`) {
		t.Fatalf("an unsendable address was not rejected: status=%d body=%s", response.Code, response.Body.String())
	}
	if got := storedEmail(); got != "a@corp.internal" {
		t.Fatalf("a rejected request must not change users.email: %q", got)
	}

	// 빈 값은 "주소를 지운다"는 뜻이라 절대 400이 아니다 — Seed 계정(email='')의
	// 프로필 저장도 이 경로를 쓴다.
	response = patch(`{"email":"  \t\r\n ","display_name":"홍길동"}`)
	if response.Code != http.StatusOK {
		t.Fatalf("a blank address must clear the value, not fail: status=%d body=%s", response.Code, response.Body.String())
	}
	if got := storedEmail(); got != "" {
		t.Fatalf("a blank address must clear users.email: %q", got)
	}
}
package store

import (
	"context"
	"fmt"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/hkjang/jupiq/internal/mail"
	"github.com/hkjang/jupiq/internal/secure"
)

// 메일 기능이 저장소에서 빌려 쓰는 조회들이 실제 PostgreSQL에서 계약대로
// 동작하는지 — 기본값은 꺼짐, 비밀번호는 secrets로만, 발송 기록은 성공·실패
// 모두, 만료 임박 키는 한 번만.
func TestMailStoreContractsIntegration(t *testing.T) {
	dsn := os.Getenv("JUPIQ_INTEGRATION_TEST_DSN")
	if dsn == "" {
		t.Skip("set JUPIQ_INTEGRATION_TEST_DSN to run PostgreSQL integration coverage")
	}
	ctx := context.Background()
	cipher, err := secure.NewCipher(make([]byte, 32))
	if err != nil {
		t.Fatal(err)
	}
	database, err := Open(ctx, dsn, cipher)
	if err != nil {
		t.Fatal(err)
	}
	defer database.Close()
	marker := fmt.Sprintf("mail-%d", time.Now().UnixNano())
	if err := database.Seed(ctx, marker, "IntegrationPassword!123"); err != nil {
		t.Fatal(err)
	}
	var adminID int64
	if err := database.Pool.QueryRow(ctx, `SELECT id FROM users WHERE username=$1`, marker).Scan(&adminID); err != nil {
		t.Fatal(err)
	}
	var previousMail []byte
	if err := database.Pool.QueryRow(ctx, `SELECT value FROM settings WHERE setting_key=$1`, mail.SettingKey).Scan(&previousMail); err != nil {
		t.Fatal(err)
	}
	defer func() {
		_, _ = database.Pool.Exec(ctx, `UPDATE settings SET value=$2 WHERE setting_key=$1`, mail.SettingKey, previousMail)
		_, _ = database.Pool.Exec(ctx, `DELETE FROM mail_deliveries WHERE actor_user_id=$1 OR recipient LIKE $2`, adminID, marker+"%")
		_, _ = database.Pool.Exec(ctx, `DELETE FROM secrets WHERE secret_key=$1`, mail.SecretKey)
		_, _ = database.Pool.Exec(ctx, `DELETE FROM users WHERE username LIKE $1`, marker+"%")
	}()

	// 새로 설치한 곳: 꺼져 있고 비밀번호가 없다.
	raw, password, err := database.MailSettings(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if config := mail.ParseConfig(raw, password); config.Enabled || password != "" || config.Port != 25 {
		t.Fatalf("fresh install must be disabled with relay defaults: %+v", config)
	}

	// 비밀번호는 secrets에 암호화 저장되고 설정 문서에는 나타나지 않는다.
	if err := database.UpdateSettingsAndSecrets(ctx, map[string]any{mail.SettingKey: map[string]any{"enabled": true, "smtp_host": "relay.internal", "from_address": "jupiq@corp.internal", "username": "jupiq"}}, map[string]string{mail.SecretKey: "s3cret"}, adminID); err != nil {
		t.Fatal(err)
	}
	raw, password, err = database.MailSettings(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if password != "s3cret" || string(raw) == "" {
		t.Fatalf("password must come back decrypted from secrets: %q", password)
	}
	settings, err := database.ListSettings(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if doc := string(settings[mail.SettingKey]); strings.Contains(doc, "s3cret") || strings.Contains(doc, "password") {
		t.Fatalf("settings document leaks the password: %s", doc)
	}
	status, err := database.SecretStatus(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if _, configured := status[mail.SecretKey]; !configured {
		t.Fatal("secret status must report mail.password as configured")
	}
	// 릴레이 주소를 바꾸면 비밀번호를 다시 입력해야 한다(다른 연동과 같은 규칙).
	if err := database.UpdateSettingsAndSecrets(ctx, map[string]any{mail.SettingKey: map[string]any{"enabled": true, "smtp_host": "other.internal", "from_address": "jupiq@corp.internal"}}, nil, adminID); err != ErrSettingsSecretReentry {
		t.Fatalf("host change without password must require re-entry: %v", err)
	}

	// 수신자 조회: 활성이고 주소가 있는 사용자만.
	if _, err := database.Pool.Exec(ctx, `UPDATE users SET email=$2 WHERE id=$1`, adminID, marker+"@corp.internal"); err != nil {
		t.Fatal(err)
	}
	emails, err := database.UserEmails(ctx, []int64{adminID, -1})
	if err != nil {
		t.Fatal(err)
	}
	if emails[adminID] != marker+"@corp.internal" || len(emails) != 1 {
		t.Fatalf("email lookup: %v", emails)
	}
	admins, err := database.UsersWithGlobalPermission(ctx, "hubs:write")
	if err != nil {
		t.Fatal(err)
	}
	if !containsInt64(admins, adminID) {
		t.Fatalf("super admin (*) must hold hubs:write: %v", admins)
	}

	// 발송 기록: 성공과 실패가 모두 남고 본문 열은 없다.
	sentID, err := database.RecordMailDelivery(ctx, mail.Delivery{Event: mail.EventTest, Recipient: marker + "@corp.internal", Subject: "시험", ActorUserID: &adminID})
	if err != nil {
		t.Fatal(err)
	}
	failedID, err := database.RecordMailDelivery(ctx, mail.Delivery{Event: mail.EventHubHealth, Recipient: marker + "@corp.internal", Subject: "Hub 실패", Reference: "hub:1"})
	if err != nil {
		t.Fatal(err)
	}
	if err := database.FinishMailDelivery(ctx, sentID, mail.StatusSent, 1, ""); err != nil {
		t.Fatal(err)
	}
	if err := database.FinishMailDelivery(ctx, failedID, mail.StatusFailed, 2, "connection refused"); err != nil {
		t.Fatal(err)
	}
	if err := database.FinishMailDelivery(ctx, failedID, "queued", 1, ""); err == nil {
		t.Fatal("finish must refuse to move a delivery back to queued")
	}
	page, err := database.ListMailDeliveries(ctx, "", 200)
	if err != nil {
		t.Fatal(err)
	}
	var sawSent, sawFailed bool
	for _, item := range page.Items {
		switch item.ID {
		case sentID:
			sawSent = item.Status == mail.StatusSent && item.Attempts == 1 && item.ActorUserID != nil && *item.ActorUserID == adminID
		case failedID:
			sawFailed = item.Status == mail.StatusFailed && item.Attempts == 2 && item.ErrorMessage == "connection refused" && item.Reference == "hub:1"
		}
	}
	if !sawSent || !sawFailed || page.Summary[mail.StatusSent] < 1 || page.Summary[mail.StatusFailed] < 1 {
		t.Fatalf("both outcomes must be listed with a summary: %+v", page)
	}
	if only, err := database.ListMailDeliveries(ctx, mail.StatusFailed, 200); err != nil || len(only.Items) == 0 || only.Items[0].Status != mail.StatusFailed {
		t.Fatalf("status filter: %v %+v", err, only)
	}

	// 만료 임박 키: 7일 안의 활성 키만, 한 번만.
	soon := time.Now().Add(3 * 24 * time.Hour)
	later := time.Now().Add(30 * 24 * time.Hour)
	if _, _, err := database.CreateAPIKey(ctx, adminID, marker+"-soon", []string{"hubs:read"}, &soon, nil); err != nil {
		t.Fatal(err)
	}
	if _, _, err := database.CreateAPIKey(ctx, adminID, marker+"-later", []string{"hubs:read"}, &later, nil); err != nil {
		t.Fatal(err)
	}
	expiring, err := database.ExpiringAPIKeys(ctx, 7*24*time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	if keys := expiring[adminID]; len(keys) != 1 || keys[0].Name != marker+"-soon" || keys[0].Prefix == "" {
		t.Fatalf("only the key expiring within the window must be returned: %+v", expiring)
	}
	again, err := database.ExpiringAPIKeys(ctx, 7*24*time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	if len(again[adminID]) != 0 {
		t.Fatalf("a key must be reported once: %+v", again)
	}

	// 보낼 주소가 없는 소유자의 키는 표시하지 않는다. Notify는 주소가 0개면
	// mail_deliveries도 로그도 남기지 않고 돌아가므로, 여기서 안내한 것으로
	// 표시하면 그 키는 어디에도 흔적 없이 조용히 만료된다.
	silentID := createTestUser(ctx, t, database, marker+"-silent", "")
	inactiveID := createTestUser(ctx, t, database, marker+"-inactive", marker+"-inactive@corp.internal")
	if _, err := database.Pool.Exec(ctx, `UPDATE users SET active=false WHERE id=$1`, inactiveID); err != nil {
		t.Fatal(err)
	}
	// UpdateProfile은 이제 입력을 다듬어 저장하지만, 관리자가 직접 넣은 행이나
	// 다듬기 이전에 저장된 행에는 공백류만 든 주소가 남아 있다(여기서도 직접
	// INSERT한다). 공백 하나만이 아니라 탭·줄바꿈·NBSP까지 세운다 — Go의 TrimSpace가 지우는
	// 문자는 전부 "보낼 곳이 없다"로 읽혀야 한다(btrim은 공백만 지워 여기서 갈렸다).
	blankForms := map[string]string{
		"spaces": "   ",
		"tab":    "\t",
		"crlf":   "\r\n",
		"nbsp":   "\u00a0",
		"mixed":  " \t\r\n\v\f\u0085\u00a0\u2028\u3000",
	}
	unreachableOwners := []int64{silentID, inactiveID}
	for name, address := range blankForms {
		if strings.TrimSpace(address) != "" {
			t.Fatalf("test data %s must be blank after TrimSpace: %q", name, address)
		}
		unreachableOwners = append(unreachableOwners, createTestUser(ctx, t, database, marker+"-blank-"+name, address))
	}
	blankOwners := unreachableOwners[2:]
	// 반대쪽 경계: 공백에 둘러싸인 멀쩡한 주소는 resolve가 다듬어 실제로 보내니
	// 조건이 이것까지 걸러서는 안 된다.
	paddedID := createTestUser(ctx, t, database, marker+"-padded", "\t "+marker+"-padded@corp.internal \r\n")
	for _, owner := range append([]int64{paddedID}, unreachableOwners...) {
		if _, _, err := database.CreateAPIKey(ctx, owner, fmt.Sprintf("%s-unreachable-%d", marker, owner), []string{"hubs:read"}, &soon, nil); err != nil {
			t.Fatal(err)
		}
	}
	unreachable, err := database.ExpiringAPIKeys(ctx, 7*24*time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	for _, owner := range unreachableOwners {
		if len(unreachable[owner]) != 0 {
			t.Fatalf("keys of owner %d with no deliverable address must not be reported: %+v", owner, unreachable)
		}
	}
	if keys := unreachable[paddedID]; len(keys) != 1 {
		t.Fatalf("a whitespace-padded but deliverable address must still be notified: %+v", unreachable)
	}
	for _, owner := range unreachableOwners {
		var notified *time.Time
		if err := database.Pool.QueryRow(ctx, `SELECT expiry_notified_at FROM api_keys WHERE user_id=$1`, owner).Scan(&notified); err != nil {
			t.Fatal(err)
		}
		if notified != nil {
			t.Fatalf("expiry_notified_at must stay NULL for owner %d: %v", owner, *notified)
		}
	}

	// 관리자가 주소를 채우면 그때 안내 기회가 살아 있어 한 번 나온다.
	if _, err := database.Pool.Exec(ctx, `UPDATE users SET email=$2 WHERE id=$1`, silentID, marker+"-silent@corp.internal"); err != nil {
		t.Fatal(err)
	}
	reachable, err := database.ExpiringAPIKeys(ctx, 7*24*time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	if keys := reachable[silentID]; len(keys) != 1 || keys[0].Name != fmt.Sprintf("%s-unreachable-%d", marker, silentID) {
		t.Fatalf("filling in the address must hand the key over once: %+v", reachable)
	}
	if len(reachable[inactiveID]) != 0 {
		t.Fatalf("an inactive owner must stay out of the notification: %+v", reachable)
	}
	for _, owner := range blankOwners {
		if len(reachable[owner]) != 0 {
			t.Fatalf("blank-address owner %d must stay out of the notification: %+v", owner, reachable)
		}
	}
	if last, err := database.ExpiringAPIKeys(ctx, 7*24*time.Hour); err != nil || len(last[silentID]) != 0 {
		t.Fatalf("the key must still be reported only once: %v %+v", err, last)
	}
}

// createTestUser는 통합 테스트용 지역 계정을 만든다. Seed와 달리 email을 직접
// 정해 수신자 해석 경로를 구분해 볼 수 있게 한다.
func createTestUser(ctx context.Context, t *testing.T, database *Store, username, email string) int64 {
	t.Helper()
	var id int64
	if err := database.Pool.QueryRow(ctx, `
		INSERT INTO users(username, display_name, email, auth_source)
		VALUES($1,$1,$2,'local') RETURNING id`, username, email).Scan(&id); err != nil {
		t.Fatal(err)
	}
	return id
}
package api

import (
	"context"
	"errors"
	"net/http"
	"strings"

	"github.com/hkjang/jupiq/internal/mail"
	"github.com/hkjang/jupiq/internal/store"
)

func (s *Server) registerMail(mux router) {
	mux.HandleFunc("GET /api/v1/mail/deliveries", s.require("settings:read", s.mailDeliveries))
	mux.HandleFunc("POST /api/v1/mail/test", s.require("settings:write", s.mailTest))
}

// mailDeliveries는 무엇이 건물 밖으로 나갔는지 보여 준다. 본문은 기록에 없다.
func (s *Server) mailDeliveries(w http.ResponseWriter, r *http.Request) {
	limit, ok := queryIntOrReject(w, r, "limit", 50)
	if !ok {
		return
	}
	page, err := s.Store.ListMailDeliveries(r.Context(), r.URL.Query().Get("status"), limit)
	if err != nil {
		handleStoreError(w, r, err)
		return
	}
	data(w, http.StatusOK, page)
}

// mailTest는 저장된 설정으로 실제 한 통을 보내고 결과를 그 자리에서 돌려준다.
// 릴레이 설정은 한 번에 맞는 일이 드물다.
func (s *Server) mailTest(w http.ResponseWriter, r *http.Request) {
	var input struct {
		Recipient string `json:"recipient"`
	}
	if err := decodeJSON(r, &input); err != nil {
		apiError(w, r, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	p := principal(r)
	recipient := strings.TrimSpace(input.Recipient)
	if recipient == "" {
		recipient = strings.TrimSpace(p.User.Email)
	}
	if !mail.ValidAddress(recipient) {
		apiError(w, r, http.StatusBadRequest, "invalid_recipient", "수신자 메일 주소를 입력해 주세요")
		return
	}
	if s.Mail == nil {
		apiError(w, r, http.StatusServiceUnavailable, "mail_unavailable", "메일 서비스가 구성되지 않았습니다")
		return
	}
	err := s.Mail.SendNow(r.Context(), mail.TestMessage(), p.User.ID, recipient)
	_ = s.Store.RecordAudit(r.Context(), requestAudit(r, "mail.test", "mail", "", map[bool]string{true: "success", false: "failure"}[err == nil], errorText(err), nil, map[string]any{"recipient": recipient}))
	switch {
	case err == nil:
		data(w, http.StatusOK, map[string]any{"sent": true, "recipient": recipient})
	case errors.Is(err, mail.ErrDisabled):
		apiError(w, r, http.StatusConflict, "mail_disabled", "메일 알림이 꺼져 있습니다. 켜고 저장한 뒤 다시 시도하세요")
	case errors.Is(err, mail.ErrInvalid):
		apiError(w, r, http.StatusBadRequest, "mail_invalid", err.Error())
	default:
		apiError(w, r, http.StatusBadGateway, "mail_send_failed", "시험 발송에 실패했습니다: "+err.Error())
	}
}

func errorText(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

// notifyMail은 메일 서비스가 있을 때만 알림을 보낸다. 모든 호출자가 요청 경로
// 위에 있으므로 실패는 사용자에게 드러나지 않는다.
func (s *Server) notifyMail(ctx context.Context, notification mail.Notification, actorUserID int64, recipients []int64) {
	if s.Mail == nil || len(recipients) == 0 {
		return
	}
	s.Mail.Notify(ctx, notification, actorUserID, recipients)
}

// notifyPermissionHolders는 전역으로 그 권한을 가진 사람 모두에게 보낸다.
func (s *Server) notifyPermissionHolders(ctx context.Context, notification mail.Notification, actorUserID int64, permission string) {
	if s.Mail == nil {
		return
	}
	recipients, err := s.Store.UsersWithGlobalPermission(ctx, permission)
	if err != nil {
		s.Logger.Warn("mail recipients lookup failed", "permission", permission, "error", err)
		return
	}
	s.notifyMail(ctx, notification, actorUserID, recipients)
}

// notifyHubHealth는 Hub 상태가 실제로 바뀌었을 때만 Hub 관리자에게 알린다.
// previous는 이번 결과를 쓰기 전에 읽은 Hub라 그 Status가 직전 상태다.
func (s *Server) notifyHubHealth(ctx context.Context, previous store.Hub, stored, success bool, cause string, actorUserID int64) {
	if s.Mail == nil || !stored {
		return
	}
	if notification, changed := mail.HubHealthChange(previous.ID, previous.Name, previous.Status, success, cause); changed {
		s.notifyPermissionHolders(ctx, notification, actorUserID, "hubs:write")
	}
}

// approvalRequesterName은 승인 요청 문서에서 요청자 이름을 읽는다.
func approvalRequesterName(details map[string]any) string {
	name, _ := details["requested_by"].(string)
	if strings.TrimSpace(name) == "" {
		return "알 수 없는 사용자"
	}
	return name
}

// approvalOwner는 결과를 받을 요청자다. 승인 요청은 대상 작업 API가 요청자를
// 소유자로 만들므로 소유자가 곧 요청자다.
func approvalOwner(approval store.Resource) []int64 {
	if approval.OwnerUserID == nil {
		return nil
	}
	return []int64{*approval.OwnerUserID}
}
package store

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"time"

	"github.com/hkjang/jupiq/internal/mail"
)

// mailDeliveryRetention은 발송 기록을 남겨 두는 기간이다. 하루에 몇 통이라
// 부담은 작지만 무한히 쌓이지는 않게 한다.
const mailDeliveryRetention = 180 * 24 * time.Hour

// nonBlankEmailPattern은 "Go의 strings.TrimSpace로 다듬어도 뭔가 남는다"를
// PostgreSQL 정규식으로 옮긴 것이다. 수신자 해석(UserEmails → mail의 resolve)이
// TrimSpace로 판정하므로 SQL도 같은 문자 집합을 봐야 한다. POSIX [[:space:]]는
// 쓰지 않는다 — 로케일에 따라 NBSP(U+00A0)·Ogham 공백을 공백으로 세지 않아
// 판정이 갈린다(PostgreSQL 16 UTF8에서 확인). 열거한 문자는 unicode.IsSpace의
// 집합 그대로다: 공백·탭·LF·VT·FF·CR·NEL·NBSP와 Zs/Zl/Zp. Go가 이스케이프를
// 풀어 보내므로 PostgreSQL은 문자 그대로를 담은 대괄호식을 받는다.
const nonBlankEmailPattern = "[^ \t\n\v\f\r\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]"

// MailSettings는 mail 문서와 SMTP 비밀번호를 한 MVCC 스냅샷으로 돌려준다.
// 문서가 없으면 빈 값이고(꺼짐), 비밀번호가 없으면 빈 문자열이다.
func (s *Store) MailSettings(ctx context.Context) (json.RawMessage, string, error) {
	settings, password, _, err := s.GetSettingsAndSecret(ctx, []string{mail.SettingKey}, mail.SecretKey)
	if err != nil {
		return nil, "", err
	}
	return settings[mail.SettingKey], password, nil
}

// UserEmails는 계정 id를 메일 주소로 바꾼다. 메일 기능이 자기 사용자 표를
// 갖지 않도록, users 테이블을 빌려 쓰는 유일한 자리다.
func (s *Store) UserEmails(ctx context.Context, userIDs []int64) (map[int64]string, error) {
	rows, err := s.Pool.Query(ctx, `SELECT id,email FROM users WHERE id=ANY($1) AND active AND email<>''`, userIDs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	emails := map[int64]string{}
	for rows.Next() {
		var id int64
		var email string
		if err := rows.Scan(&id, &email); err != nil {
			return nil, err
		}
		emails[id] = strings.TrimSpace(email)
	}
	return emails, rows.Err()
}

// UsersWithGlobalPermission은 전역 범위 역할로 그 권한을 가진 활성 사용자
// id다. 알림의 수신자를 정할 때 쓴다. 특정 Hub·부서로 제한된 바인딩은 대상이
// 그 범위에 드는지 알 수 없으므로 세지 않는다.
func (s *Store) UsersWithGlobalPermission(ctx context.Context, permission string) ([]int64, error) {
	rows, err := s.Pool.Query(ctx, `
		SELECT u.id, r.permissions
		FROM users u
		JOIN user_roles ur ON ur.user_id=u.id
		JOIN roles r ON r.id=ur.role_id
		WHERE u.active AND ur.scope_mode='global'
		ORDER BY u.id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	ids := []int64{}
	seen := map[int64]struct{}{}
	for rows.Next() {
		var id int64
		var raw []byte
		if err := rows.Scan(&id, &raw); err != nil {
			return nil, err
		}
		if _, done := seen[id]; done {
			continue
		}
		var permissions []string
		_ = json.Unmarshal(raw, &permissions)
		if EnsurePermission(permissions, permission) {
			seen[id] = struct{}{}
			ids = append(ids, id)
		}
	}
	return ids, rows.Err()
}

func (s *Store) RecordMailDelivery(ctx context.Context, delivery mail.Delivery) (int64, error) {
	var id int64
	err := s.Pool.QueryRow(ctx, `
		INSERT INTO mail_deliveries(event,recipient,subject,reference,actor_user_id,status,attempts)
		VALUES($1,$2,$3,$4,$5,$6,0) RETURNING id`,
		delivery.Event, delivery.Recipient, truncate(delivery.Subject, 300), truncate(delivery.Reference, 300), delivery.ActorUserID, mail.StatusQueued).Scan(&id)
	return id, err
}

func (s *Store) FinishMailDelivery(ctx context.Context, id int64, status string, attempts int, errorMessage string) error {
	if status != mail.StatusSent && status != mail.StatusFailed {
		return errors.New("mail delivery status must be sent or failed")
	}
	_, err := s.Pool.Exec(ctx, `UPDATE mail_deliveries SET status=$2,attempts=GREATEST(attempts,$3),error_message=$4,updated_at=now() WHERE id=$1`,
		id, status, attempts, truncate(errorMessage, 1000))
	return err
}

// MailDeliveryPage는 발송 기록 목록과 상태별 집계다.
type MailDeliveryPage struct {
	Items   []mail.Delivery `json:"items"`
	Total   int             `json:"total"`
	Summary map[string]int  `json:"summary"`
}

// ListMailDeliveries는 최신순 발송 기록이다. status가 비어 있지 않으면 그
// 상태만 고른다.
func (s *Store) ListMailDeliveries(ctx context.Context, status string, limit int) (MailDeliveryPage, error) {
	limit = boundedLimit(limit, 50, 200)
	page := MailDeliveryPage{Items: []mail.Delivery{}, Summary: map[string]int{}}
	rows, err := s.Pool.Query(ctx, `
		SELECT id,event,recipient,subject,reference,actor_user_id,status,attempts,error_message,created_at,updated_at
		FROM mail_deliveries WHERE $1='' OR status=$1
		ORDER BY created_at DESC, id DESC LIMIT $2`, strings.TrimSpace(status), limit)
	if err != nil {
		return page, err
	}
	defer rows.Close()
	for rows.Next() {
		var item mail.Delivery
		if err := rows.Scan(&item.ID, &item.Event, &item.Recipient, &item.Subject, &item.Reference, &item.ActorUserID, &item.Status, &item.Attempts, &item.ErrorMessage, &item.CreatedAt, &item.UpdatedAt); err != nil {
			return page, err
		}
		page.Items = append(page.Items, item)
	}
	if err := rows.Err(); err != nil {
		return page, err
	}
	counts, err := s.Pool.Query(ctx, `SELECT status, count(*) FROM mail_deliveries GROUP BY 1`)
	if err != nil {
		return page, err
	}
	defer counts.Close()
	for counts.Next() {
		var key string
		var count int
		if err := counts.Scan(&key, &count); err != nil {
			return page, err
		}
		page.Summary[key] = count
		page.Total += count
	}
	return page, counts.Err()
}

// PruneMailDeliveries는 오래된 발송 기록을 지운다.
func (s *Store) PruneMailDeliveries(ctx context.Context) error {
	_, err := s.Pool.Exec(ctx, `DELETE FROM mail_deliveries WHERE created_at < now() - $1::interval`, mailDeliveryRetention)
	return err
}

// ExpiringAPIKeys는 아직 안내하지 않은, 만료가 within 안으로 다가온 활성
// 키를 소유자별로 묶어 돌려준다. 돌려준 키는 안내한 것으로 표시하므로 릴레이가
// 죽어 있어도 같은 키에 되풀이 보내지 않는다 — 발송 실패는 기록에 남는다.
// 표시하는 것은 활성이고 다듬은 email이 비어 있지 않은 소유자의 키뿐이다
// (nonBlankEmailPattern이 수신자 해석의 TrimSpace와 같은 문자 집합을 본다).
// 주소가 없으면 Notify가 기록도 로그도 없이 돌아가므로, 표시부터 하면 그 키는
// 흔적 없이 조용히 만료된다 — 나중에 주소를 채우면 그때 한 번 안내한다.
// 다만 수신자 해석은 여기보다 좁다: resolve의 validAddress는 '@'가 없는
// email='nonsense' 같은 주소도 버린다. SQL로 주소 모양까지 흉내 내면 두 파서가
// 갈리므로 그 계열은 입구에서 막는다 — 프로필 API가 mail.ValidAddress로 거부하고
// UpdateProfile·UpsertOIDCUser가 저장 시점에 다듬는다. 그래도 관리자가 직접 넣은
// 행처럼 입구를 지나지 않은 값은 남을 수 있어, 그런 키는 여기서 표시만 된다.
func (s *Store) ExpiringAPIKeys(ctx context.Context, within time.Duration) (map[int64][]mail.ExpiringKey, error) {
	rows, err := s.Pool.Query(ctx, `
		UPDATE api_keys SET expiry_notified_at=now()
		WHERE status='active' AND expiry_notified_at IS NULL
		  AND expires_at IS NOT NULL AND expires_at > now() AND expires_at <= now() + $1::interval
		  AND user_id IN (SELECT id FROM users WHERE active AND email ~ $2)
		RETURNING id,user_id,name,prefix,expires_at`, within, nonBlankEmailPattern)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	byUser := map[int64][]mail.ExpiringKey{}
	for rows.Next() {
		var key mail.ExpiringKey
		var userID int64
		if err := rows.Scan(&key.ID, &userID, &key.Name, &key.Prefix, &key.ExpiresAt); err != nil {
			return nil, err
		}
		byUser[userID] = append(byUser[userID], key)
	}
	return byUser, rows.Err()
}

